{
  "rules": [
    {
      "id": "check_phone_format",
      "description": "Ensure that the phone numbers are in a valid format (e.g., 123-456-7890).",
      "gx_code": "gx.expectations.ExpectColumnValuesToMatchRegex(column='phone', regex='^[0-9]{3}-[0-9]{3}-[0-9]{4}$')",
      "evidence_references": ["https://www.regular-expressions.info/phonenumber.html"]
    },
    {
      "id": "check_zip_format",
      "description": "Ensure that the zip codes are in a valid format (e.g., 12345 or 12345-6789).",
      "gx_code": "gx.expectations.ExpectColumnValuesToMatchRegex(column='zip', regex='^[0-9]{5}(-[0-9]{4})?$')",
      "evidence_references": ["https://www.regular-expressions.info/zip.html"]
    },
    {
      "id": "check_state_code",
      "description": "Ensure that the state codes are in a valid format (e.g., two-letter abbreviation).",
      "gx_code": "gx.expectations.ExpectColumnValuesToMatchRegex(column='state', regex='^[A-Z]{2}$')",
      "evidence_references": ["https://en.wikipedia.org/wiki/List_of_U.S._state_abbreviations"]
    },
    {
      "id": "check_owner_type",
      "description": "Ensure that the owner types are one of the documented values (e.g., 'Public', 'Private').",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeInSet(column='owner', value_set=['Public', 'Private'])",
      "evidence_references": ["SOURCE_CONTEXT documentation"]
    }
  ],
  "abstentions": [
    "The schema does not provide specific constraints for the 'score' and 'sample' columns, so their data quality cannot be checked without additional assumptions."
  ]
}
